/** @jsxImportSource @samva/markup/email */
import { Button, Email, Image, Section } from "@samva/markup/email";
import { jsonSchema } from "@samva/markup/input-schema";
import { defineEmail } from "@samva/markup/template";
export default defineEmail({
  id: "synthetic-account-alert",
  schema: jsonSchema<{ accountUrl: string; alertBody: string; logoUrl: string }>({"type": "object", "properties": {"accountUrl": {"type": "string"}, "alertBody": {"type": "string"}, "logoUrl": {"type": "string"}}, "required": ["accountUrl", "alertBody", "logoUrl"], "additionalProperties": false}),
  fixtures: { default: {"accountUrl": "https://app.example.com/account", "alertBody": "A new recovery method was added to your account.", "logoUrl": "https://samva.dev/templates/assets/transparent-icon.png"} },
  render: (input) => ({
    subject: "Review your account",
    preheader: "A synthetic account event needs attention.",
    body: <Email lang="en" dir="ltr"><Section>
      <Image src={input.logoUrl} alt="Synthetic logo" />
      <p>{input.alertBody}</p>
      <Button href={input.accountUrl} width={200} height={48}>Open account</Button>
    </Section></Email>,
  }),
});
